SET STATISTICS IO, TIME ON;
SELECT o.OrderId, o.Total
FROM dbo.Orders AS o
WHERE o.CustomerId = 42;
-- Messages: Table 'Orders'. Scan count 1, logical reads 3 ...
--           CPU time = 0 ms, elapsed time = 1 ms.

-- Find a query's plans and force the good one
SELECT q.query_id, p.plan_id, rs.avg_duration
FROM sys.query_store_query AS q
JOIN sys.query_store_plan AS p ON p.query_id = q.query_id
JOIN sys.query_store_runtime_stats AS rs ON rs.plan_id = p.plan_id
WHERE q.query_id = 42;

EXEC sp_query_store_force_plan @query_id = 42, @plan_id = 7;

-- Hint without changing application code
EXEC sp_query_store_set_hints @query_id = 42, @query_hints = N'OPTION(RECOMPILE)';
